-- Resoloon CRM core schema. PostgreSQL 17; UUIDs are generated by PostgreSQL.
-- Migrations are applied transactionally by src/migrate.ts.

CREATE TABLE workspaces (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL CHECK (btrim(name) <> ''),
  default_timezone text NOT NULL DEFAULT 'Europe/Budapest',
  default_currency char(3) NOT NULL DEFAULT 'EUR' CHECK (default_currency ~ '^[A-Z]{3}$'),
  workflow_settings jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(workflow_settings) = 'object'),
  settings_version integer NOT NULL DEFAULT 1 CHECK (settings_version > 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE users (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT,
  full_name text NOT NULL CHECK (btrim(full_name) <> ''),
  email text NOT NULL CHECK (btrim(email) <> ''),
  email_normalized text GENERATED ALWAYS AS (lower(btrim(email))) STORED,
  role text NOT NULL DEFAULT 'USER' CHECK (role IN ('ADMIN', 'USER')),
  state text NOT NULL DEFAULT 'SETUP_REQUIRED' CHECK (state IN ('SETUP_REQUIRED', 'ACTIVE', 'DEACTIVATED')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (id, workspace_id),
  UNIQUE (workspace_id, email_normalized)
);

CREATE INDEX users_workspace_state_idx ON users (workspace_id, state, full_name);

CREATE TABLE password_credentials (
  user_id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL,
  algorithm text NOT NULL DEFAULT 'scrypt' CHECK (algorithm = 'scrypt'),
  password_hash bytea NOT NULL CHECK (octet_length(password_hash) >= 32),
  salt bytea NOT NULL CHECK (octet_length(salt) >= 16),
  parameters jsonb NOT NULL CHECK (jsonb_typeof(parameters) = 'object'),
  force_reset boolean NOT NULL DEFAULT false,
  updated_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (user_id, workspace_id) REFERENCES users (id, workspace_id) ON DELETE CASCADE
);

CREATE TABLE sessions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid NOT NULL,
  user_id uuid NOT NULL,
  token_hash bytea NOT NULL UNIQUE CHECK (octet_length(token_hash) = 32),
  created_at timestamptz NOT NULL DEFAULT now(),
  last_used_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  revoked_at timestamptz,
  user_agent text,
  CHECK (expires_at > created_at),
  FOREIGN KEY (user_id, workspace_id) REFERENCES users (id, workspace_id) ON DELETE CASCADE
);

CREATE INDEX sessions_user_active_idx ON sessions (workspace_id, user_id, expires_at)
  WHERE revoked_at IS NULL;
CREATE INDEX sessions_expiry_idx ON sessions (expires_at) WHERE revoked_at IS NULL;

CREATE FUNCTION revoke_sessions_after_password_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  UPDATE sessions SET revoked_at = COALESCE(revoked_at, statement_timestamp())
   WHERE workspace_id = NEW.workspace_id AND user_id = NEW.user_id AND revoked_at IS NULL;
  RETURN NEW;
END;
$$;

CREATE TRIGGER password_credentials_revoke_sessions AFTER UPDATE OF password_hash, salt, parameters
  ON password_credentials FOR EACH ROW EXECUTE FUNCTION revoke_sessions_after_password_change();

CREATE FUNCTION revoke_sessions_after_deactivation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.state = 'DEACTIVATED' AND OLD.state IS DISTINCT FROM NEW.state THEN
    UPDATE sessions SET revoked_at = COALESCE(revoked_at, statement_timestamp())
     WHERE workspace_id = NEW.workspace_id AND user_id = NEW.id AND revoked_at IS NULL;
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER users_revoke_sessions_on_deactivation AFTER UPDATE OF state ON users
  FOR EACH ROW EXECUTE FUNCTION revoke_sessions_after_deactivation();

CREATE TABLE account_tokens (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid NOT NULL,
  user_id uuid NOT NULL,
  purpose text NOT NULL CHECK (purpose IN ('SETUP', 'PASSWORD_RESET')),
  token_hash bytea NOT NULL UNIQUE CHECK (octet_length(token_hash) = 32),
  created_by_actor_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  consumed_at timestamptz,
  CHECK (expires_at > created_at),
  FOREIGN KEY (user_id, workspace_id) REFERENCES users (id, workspace_id) ON DELETE CASCADE
);

CREATE INDEX account_tokens_user_open_idx ON account_tokens (workspace_id, user_id, purpose, expires_at)
  WHERE consumed_at IS NULL;

CREATE TABLE actors (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT,
  actor_type text NOT NULL CHECK (actor_type IN ('USER', 'SYSTEM', 'INTEGRATION', 'MCP_CLIENT', 'IMPORT')),
  user_id uuid,
  owner_user_id uuid,
  external_actor_key text,
  display_name text NOT NULL CHECK (btrim(display_name) <> ''),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (id, workspace_id),
  FOREIGN KEY (user_id, workspace_id) REFERENCES users (id, workspace_id) ON DELETE RESTRICT,
  FOREIGN KEY (owner_user_id, workspace_id) REFERENCES users (id, workspace_id) ON DELETE RESTRICT,
  CHECK (
    (actor_type = 'USER' AND user_id IS NOT NULL AND external_actor_key IS NULL)
    OR (actor_type = 'SYSTEM' AND user_id IS NULL AND owner_user_id IS NULL AND external_actor_key IS NOT NULL)
    OR (actor_type IN ('INTEGRATION', 'MCP_CLIENT', 'IMPORT') AND user_id IS NULL AND external_actor_key IS NOT NULL)
  )
);

CREATE UNIQUE INDEX actors_user_unique_idx ON actors (workspace_id, user_id) WHERE actor_type = 'USER';
CREATE UNIQUE INDEX actors_external_unique_idx ON actors (workspace_id, actor_type, external_actor_key)
  WHERE external_actor_key IS NOT NULL;

ALTER TABLE account_tokens
  ADD CONSTRAINT account_tokens_creator_fk
  FOREIGN KEY (created_by_actor_id, workspace_id) REFERENCES actors (id, workspace_id) ON DELETE RESTRICT;

CREATE TABLE records (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT,
  record_type text NOT NULL CHECK (record_type IN ('PERSON', 'COMPANY', 'OPPORTUNITY', 'NOTE')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  created_by_actor_id uuid NOT NULL,
  updated_by_actor_id uuid NOT NULL,
  version integer NOT NULL DEFAULT 1 CHECK (version > 0),
  archived_at timestamptz,
  merged_into_record_id uuid,
  UNIQUE (id, workspace_id),
  FOREIGN KEY (created_by_actor_id, workspace_id) REFERENCES actors (id, workspace_id) ON DELETE RESTRICT,
  FOREIGN KEY (updated_by_actor_id, workspace_id) REFERENCES actors (id, workspace_id) ON DELETE RESTRICT,
  FOREIGN KEY (merged_into_record_id, workspace_id) REFERENCES records (id, workspace_id) ON DELETE RESTRICT,
  CHECK (merged_into_record_id IS NULL OR merged_into_record_id <> id),
  CHECK (merged_into_record_id IS NULL OR archived_at IS NOT NULL)
);

CREATE INDEX records_workspace_type_updated_idx ON records (workspace_id, record_type, updated_at DESC, id);
CREATE INDEX records_workspace_live_idx ON records (workspace_id, record_type, id) WHERE archived_at IS NULL;
CREATE INDEX records_merged_into_idx ON records (workspace_id, merged_into_record_id) WHERE merged_into_record_id IS NOT NULL;

CREATE FUNCTION protect_record_identity() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id
     OR NEW.record_type IS DISTINCT FROM OLD.record_type
     OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR NEW.created_by_actor_id IS DISTINCT FROM OLD.created_by_actor_id THEN
    RAISE EXCEPTION 'record identity and creation attribution are immutable'
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF NEW.version <> OLD.version + 1 THEN
    RAISE EXCEPTION 'record version must increase by exactly one'
      USING ERRCODE = 'serialization_failure';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER records_identity_immutable BEFORE UPDATE ON records
  FOR EACH ROW EXECUTE FUNCTION protect_record_identity();

CREATE FUNCTION enforce_record_type() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE actual_type text;
BEGIN
  SELECT record_type INTO actual_type FROM records
   WHERE id = NEW.id AND workspace_id = NEW.workspace_id;
  IF actual_type IS DISTINCT FROM TG_ARGV[0] THEN
    RAISE EXCEPTION 'record % in workspace % must have type %, found %', NEW.id, NEW.workspace_id, TG_ARGV[0], actual_type
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TABLE people (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL,
  full_name text NOT NULL CHECK (btrim(full_name) <> ''),
  normalized_name text NOT NULL CHECK (btrim(normalized_name) <> ''),
  job_title text,
  description text,
  importance smallint CHECK (importance IS NULL OR importance BETWEEN 0 AND 5),
  introduced_by_person_id uuid,
  UNIQUE (id, workspace_id),
  FOREIGN KEY (id, workspace_id) REFERENCES records (id, workspace_id) ON DELETE CASCADE,
  FOREIGN KEY (introduced_by_person_id, workspace_id) REFERENCES people (id, workspace_id) ON DELETE RESTRICT
);

CREATE TRIGGER people_record_type BEFORE INSERT OR UPDATE ON people
  FOR EACH ROW EXECUTE FUNCTION enforce_record_type('PERSON');
CREATE INDEX people_workspace_name_idx ON people (workspace_id, normalized_name, id);

CREATE TABLE person_emails (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid NOT NULL,
  person_id uuid NOT NULL,
  raw_email text NOT NULL CHECK (btrim(raw_email) <> ''),
  normalized_email text NOT NULL CHECK (btrim(normalized_email) <> ''),
  is_primary boolean NOT NULL DEFAULT false,
  match_enabled boolean NOT NULL DEFAULT true,
  provenance jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(provenance) = 'object'),
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (person_id, workspace_id) REFERENCES people (id, workspace_id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX person_emails_primary_idx ON person_emails (workspace_id, person_id) WHERE is_primary;
CREATE UNIQUE INDEX person_emails_match_identity_idx ON person_emails (workspace_id, normalized_email) WHERE match_enabled;
CREATE INDEX person_emails_person_idx ON person_emails (workspace_id, person_id, id);

CREATE TABLE person_phones (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid NOT NULL,
  person_id uuid NOT NULL,
  raw_phone text NOT NULL CHECK (btrim(raw_phone) <> ''),
  e164 text CHECK (e164 IS NULL OR e164 ~ '^\+[1-9][0-9]{1,14}$'),
  is_primary boolean NOT NULL DEFAULT false,
  provenance jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(provenance) = 'object'),
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (person_id, workspace_id) REFERENCES people (id, workspace_id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX person_phones_primary_idx ON person_phones (workspace_id, person_id) WHERE is_primary;
CREATE UNIQUE INDEX person_phones_e164_identity_idx ON person_phones (workspace_id, e164) WHERE e164 IS NOT NULL;

CREATE TABLE person_links (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid NOT NULL,
  person_id uuid NOT NULL,
  kind text NOT NULL CHECK (btrim(kind) <> ''),
  raw_url text NOT NULL CHECK (btrim(raw_url) <> ''),
  canonical_url text NOT NULL CHECK (btrim(canonical_url) <> ''),
  is_primary boolean NOT NULL DEFAULT false,
  provenance jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(provenance) = 'object'),
  FOREIGN KEY (person_id, workspace_id) REFERENCES people (id, workspace_id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX person_links_primary_idx ON person_links (workspace_id, person_id) WHERE is_primary;
CREATE UNIQUE INDEX person_links_canonical_idx ON person_links (workspace_id, canonical_url);

CREATE TABLE person_addresses (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid NOT NULL,
  person_id uuid NOT NULL,
  label text,
  street text,
  city text,
  region text,
  postal_code text,
  country_code char(2) CHECK (country_code IS NULL OR country_code ~ '^[A-Z]{2}$'),
  latitude double precision CHECK (latitude IS NULL OR latitude BETWEEN -90 AND 90),
  longitude double precision CHECK (longitude IS NULL OR longitude BETWEEN -180 AND 180),
  provider_place_id text,
  is_primary boolean NOT NULL DEFAULT false,
  FOREIGN KEY (person_id, workspace_id) REFERENCES people (id, workspace_id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX person_addresses_primary_idx ON person_addresses (workspace_id, person_id) WHERE is_primary;
CREATE INDEX person_addresses_city_idx ON person_addresses (workspace_id, city) WHERE city IS NOT NULL;

CREATE TABLE companies (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL,
  name text NOT NULL CHECK (btrim(name) <> ''),
  normalized_name text NOT NULL CHECK (btrim(normalized_name) <> ''),
  description text,
  owner_user_id uuid,
  customer_profile text,
  business_role text,
  UNIQUE (id, workspace_id),
  FOREIGN KEY (id, workspace_id) REFERENCES records (id, workspace_id) ON DELETE CASCADE,
  FOREIGN KEY (owner_user_id, workspace_id) REFERENCES users (id, workspace_id) ON DELETE RESTRICT
);

CREATE TRIGGER companies_record_type BEFORE INSERT OR UPDATE ON companies
  FOR EACH ROW EXECUTE FUNCTION enforce_record_type('COMPANY');
CREATE INDEX companies_workspace_name_idx ON companies (workspace_id, normalized_name, id);

CREATE TABLE company_domains (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid NOT NULL,
  company_id uuid NOT NULL,
  raw_domain text NOT NULL CHECK (btrim(raw_domain) <> ''),
  normalized_domain text NOT NULL CHECK (
    normalized_domain = lower(btrim(normalized_domain)) AND
    normalized_domain !~ '^www\.' AND normalized_domain !~ '[/@: ]'
  ),
  is_primary boolean NOT NULL DEFAULT false,
  provenance jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(provenance) = 'object'),
  FOREIGN KEY (company_id, workspace_id) REFERENCES companies (id, workspace_id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX company_domains_identity_idx ON company_domains (workspace_id, normalized_domain);
CREATE UNIQUE INDEX company_domains_primary_idx ON company_domains (workspace_id, company_id) WHERE is_primary;

CREATE TABLE company_links (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid NOT NULL,
  company_id uuid NOT NULL,
  kind text NOT NULL CHECK (btrim(kind) <> ''),
  raw_url text NOT NULL CHECK (btrim(raw_url) <> ''),
  canonical_url text NOT NULL CHECK (btrim(canonical_url) <> ''),
  is_primary boolean NOT NULL DEFAULT false,
  provenance jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(provenance) = 'object'),
  FOREIGN KEY (company_id, workspace_id) REFERENCES companies (id, workspace_id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX company_links_primary_idx ON company_links (workspace_id, company_id) WHERE is_primary;
CREATE UNIQUE INDEX company_links_canonical_idx ON company_links (workspace_id, canonical_url);

CREATE TABLE company_addresses (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid NOT NULL,
  company_id uuid NOT NULL,
  label text,
  street text,
  city text,
  region text,
  postal_code text,
  country_code char(2) CHECK (country_code IS NULL OR country_code ~ '^[A-Z]{2}$'),
  latitude double precision CHECK (latitude IS NULL OR latitude BETWEEN -90 AND 90),
  longitude double precision CHECK (longitude IS NULL OR longitude BETWEEN -180 AND 180),
  provider_place_id text,
  is_primary boolean NOT NULL DEFAULT false,
  FOREIGN KEY (company_id, workspace_id) REFERENCES companies (id, workspace_id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX company_addresses_primary_idx ON company_addresses (workspace_id, company_id) WHERE is_primary;
CREATE INDEX company_addresses_city_idx ON company_addresses (workspace_id, city) WHERE city IS NOT NULL;

CREATE TABLE person_companies (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid NOT NULL,
  person_id uuid NOT NULL,
  company_id uuid NOT NULL,
  job_title text,
  role text,
  is_primary boolean NOT NULL DEFAULT false,
  started_on date,
  ended_on date,
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK (ended_on IS NULL OR started_on IS NULL OR ended_on >= started_on),
  UNIQUE (workspace_id, person_id, company_id),
  FOREIGN KEY (person_id, workspace_id) REFERENCES people (id, workspace_id) ON DELETE CASCADE,
  FOREIGN KEY (company_id, workspace_id) REFERENCES companies (id, workspace_id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX person_companies_current_primary_idx ON person_companies (workspace_id, person_id)
  WHERE is_primary AND ended_on IS NULL;
CREATE INDEX person_companies_company_idx ON person_companies (workspace_id, company_id, person_id);

CREATE TABLE opportunities (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL,
  name text NOT NULL CHECK (btrim(name) <> ''),
  description text,
  stage text NOT NULL DEFAULT 'LEAD' CHECK (stage IN ('LEAD', 'QUALIFIED', 'PROPOSAL', 'NEGOTIATION', 'WON', 'LOST')),
  value numeric(18, 2) CHECK (value IS NULL OR value >= 0),
  currency char(3) NOT NULL DEFAULT 'EUR' CHECK (currency ~ '^[A-Z]{3}$'),
  owner_user_id uuid,
  expected_close_date date,
  next_action text,
  next_follow_up_at timestamptz,
  won_at timestamptz,
  lost_at timestamptz,
  lost_reason text,
  UNIQUE (id, workspace_id),
  FOREIGN KEY (id, workspace_id) REFERENCES records (id, workspace_id) ON DELETE CASCADE,
  FOREIGN KEY (owner_user_id, workspace_id) REFERENCES users (id, workspace_id) ON DELETE RESTRICT,
  CHECK (stage <> 'WON' OR won_at IS NOT NULL),
  CHECK (stage <> 'LOST' OR lost_at IS NOT NULL)
);

CREATE TRIGGER opportunities_record_type BEFORE INSERT OR UPDATE ON opportunities
  FOR EACH ROW EXECUTE FUNCTION enforce_record_type('OPPORTUNITY');
CREATE INDEX opportunities_pipeline_idx ON opportunities (workspace_id, stage, expected_close_date, id);
CREATE INDEX opportunities_owner_idx ON opportunities (workspace_id, owner_user_id, stage);

CREATE TABLE opportunity_people (
  workspace_id uuid NOT NULL,
  opportunity_id uuid NOT NULL,
  person_id uuid NOT NULL,
  relationship text,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (workspace_id, opportunity_id, person_id),
  FOREIGN KEY (opportunity_id, workspace_id) REFERENCES opportunities (id, workspace_id) ON DELETE CASCADE,
  FOREIGN KEY (person_id, workspace_id) REFERENCES people (id, workspace_id) ON DELETE CASCADE
);

CREATE INDEX opportunity_people_person_idx ON opportunity_people (workspace_id, person_id, opportunity_id);

CREATE TABLE opportunity_companies (
  workspace_id uuid NOT NULL,
  opportunity_id uuid NOT NULL,
  company_id uuid NOT NULL,
  relationship text,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (workspace_id, opportunity_id, company_id),
  FOREIGN KEY (opportunity_id, workspace_id) REFERENCES opportunities (id, workspace_id) ON DELETE CASCADE,
  FOREIGN KEY (company_id, workspace_id) REFERENCES companies (id, workspace_id) ON DELETE CASCADE
);

CREATE INDEX opportunity_companies_company_idx ON opportunity_companies (workspace_id, company_id, opportunity_id);

CREATE TABLE notes (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL,
  note_type text NOT NULL DEFAULT 'GENERAL' CHECK (note_type IN ('GENERAL', 'MEETING')),
  title text NOT NULL CHECK (btrim(title) <> ''),
  body_markdown text NOT NULL DEFAULT '',
  legacy_content jsonb,
  UNIQUE (id, workspace_id),
  FOREIGN KEY (id, workspace_id) REFERENCES records (id, workspace_id) ON DELETE CASCADE
);

CREATE TRIGGER notes_record_type BEFORE INSERT OR UPDATE ON notes
  FOR EACH ROW EXECUTE FUNCTION enforce_record_type('NOTE');
CREATE INDEX notes_workspace_type_idx ON notes (workspace_id, note_type, id);

CREATE TABLE note_people (
  workspace_id uuid NOT NULL,
  note_id uuid NOT NULL,
  person_id uuid NOT NULL,
  PRIMARY KEY (workspace_id, note_id, person_id),
  FOREIGN KEY (note_id, workspace_id) REFERENCES notes (id, workspace_id) ON DELETE CASCADE,
  FOREIGN KEY (person_id, workspace_id) REFERENCES people (id, workspace_id) ON DELETE CASCADE
);

CREATE INDEX note_people_person_idx ON note_people (workspace_id, person_id, note_id);

CREATE TABLE note_companies (
  workspace_id uuid NOT NULL,
  note_id uuid NOT NULL,
  company_id uuid NOT NULL,
  PRIMARY KEY (workspace_id, note_id, company_id),
  FOREIGN KEY (note_id, workspace_id) REFERENCES notes (id, workspace_id) ON DELETE CASCADE,
  FOREIGN KEY (company_id, workspace_id) REFERENCES companies (id, workspace_id) ON DELETE CASCADE
);

CREATE INDEX note_companies_company_idx ON note_companies (workspace_id, company_id, note_id);

CREATE TABLE note_opportunities (
  workspace_id uuid NOT NULL,
  note_id uuid NOT NULL,
  opportunity_id uuid NOT NULL,
  PRIMARY KEY (workspace_id, note_id, opportunity_id),
  FOREIGN KEY (note_id, workspace_id) REFERENCES notes (id, workspace_id) ON DELETE CASCADE,
  FOREIGN KEY (opportunity_id, workspace_id) REFERENCES opportunities (id, workspace_id) ON DELETE CASCADE
);

CREATE INDEX note_opportunities_opportunity_idx ON note_opportunities (workspace_id, opportunity_id, note_id);

CREATE TABLE taxonomy_terms (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT,
  taxonomy text NOT NULL CHECK (taxonomy IN ('PERSON_CATEGORY', 'COMPANY_CATEGORY', 'INDUSTRY')),
  label text NOT NULL CHECK (btrim(label) <> ''),
  normalized_label text NOT NULL CHECK (btrim(normalized_label) <> ''),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (id, workspace_id),
  UNIQUE (workspace_id, taxonomy, normalized_label)
);

CREATE TABLE record_taxonomies (
  workspace_id uuid NOT NULL,
  record_id uuid NOT NULL,
  taxonomy_term_id uuid NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (workspace_id, record_id, taxonomy_term_id),
  FOREIGN KEY (record_id, workspace_id) REFERENCES records (id, workspace_id) ON DELETE CASCADE,
  FOREIGN KEY (taxonomy_term_id, workspace_id) REFERENCES taxonomy_terms (id, workspace_id) ON DELETE CASCADE
);

CREATE INDEX record_taxonomies_term_idx ON record_taxonomies (workspace_id, taxonomy_term_id, record_id);

CREATE FUNCTION enforce_taxonomy_record_type() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE current_record_type text;
DECLARE current_taxonomy text;
BEGIN
  SELECT record_type INTO current_record_type FROM records
   WHERE id = NEW.record_id AND workspace_id = NEW.workspace_id;
  SELECT taxonomy INTO current_taxonomy FROM taxonomy_terms
   WHERE id = NEW.taxonomy_term_id AND workspace_id = NEW.workspace_id;
  IF (current_taxonomy = 'PERSON_CATEGORY' AND current_record_type <> 'PERSON')
     OR (current_taxonomy IN ('COMPANY_CATEGORY', 'INDUSTRY') AND current_record_type <> 'COMPANY') THEN
    RAISE EXCEPTION 'taxonomy % cannot be applied to record type %', current_taxonomy, current_record_type
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER record_taxonomies_type_guard BEFORE INSERT OR UPDATE ON record_taxonomies
  FOR EACH ROW EXECUTE FUNCTION enforce_taxonomy_record_type();

CREATE TABLE activity_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT,
  actor_id uuid NOT NULL,
  owner_user_id uuid,
  action text NOT NULL CHECK (btrim(action) <> ''),
  primary_record_id uuid,
  source text NOT NULL CHECK (btrim(source) <> ''),
  occurred_at timestamptz NOT NULL DEFAULT now(),
  request_id text,
  correlation_id text,
  idempotency_key text,
  changed_fields jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(changed_fields) = 'object'),
  UNIQUE (id, workspace_id),
  FOREIGN KEY (actor_id, workspace_id) REFERENCES actors (id, workspace_id) ON DELETE RESTRICT,
  FOREIGN KEY (owner_user_id, workspace_id) REFERENCES users (id, workspace_id) ON DELETE RESTRICT,
  FOREIGN KEY (primary_record_id, workspace_id) REFERENCES records (id, workspace_id) ON DELETE RESTRICT
);

CREATE UNIQUE INDEX activity_idempotency_idx ON activity_events (workspace_id, actor_id, idempotency_key)
  WHERE idempotency_key IS NOT NULL;
CREATE INDEX activity_workspace_time_idx ON activity_events (workspace_id, occurred_at DESC, id DESC);
CREATE INDEX activity_primary_record_time_idx ON activity_events (workspace_id, primary_record_id, occurred_at DESC)
  WHERE primary_record_id IS NOT NULL;

CREATE TABLE activity_records (
  workspace_id uuid NOT NULL,
  activity_event_id uuid NOT NULL,
  record_id uuid NOT NULL,
  PRIMARY KEY (workspace_id, activity_event_id, record_id),
  FOREIGN KEY (activity_event_id, workspace_id) REFERENCES activity_events (id, workspace_id) ON DELETE RESTRICT,
  FOREIGN KEY (record_id, workspace_id) REFERENCES records (id, workspace_id) ON DELETE RESTRICT
);

CREATE INDEX activity_records_record_idx ON activity_records (workspace_id, record_id, activity_event_id);

CREATE FUNCTION reject_immutable_row_mutation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION '% is append-only; % is not permitted', TG_TABLE_NAME, TG_OP
    USING ERRCODE = 'integrity_constraint_violation';
END;
$$;

CREATE TRIGGER activity_events_append_only BEFORE UPDATE OR DELETE ON activity_events
  FOR EACH ROW EXECUTE FUNCTION reject_immutable_row_mutation();
CREATE TRIGGER activity_records_append_only BEFORE UPDATE OR DELETE ON activity_records
  FOR EACH ROW EXECUTE FUNCTION reject_immutable_row_mutation();
CREATE TRIGGER records_no_hard_delete BEFORE DELETE ON records
  FOR EACH ROW EXECUTE FUNCTION reject_immutable_row_mutation();

CREATE TABLE outbox_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT,
  event_type text NOT NULL CHECK (btrim(event_type) <> ''),
  deduplication_key text,
  payload jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(payload) = 'object'),
  correlation_id text,
  created_at timestamptz NOT NULL DEFAULT now(),
  available_at timestamptz NOT NULL DEFAULT now(),
  attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  claimed_at timestamptz,
  published_at timestamptz,
  last_error text
);

CREATE UNIQUE INDEX outbox_deduplication_idx ON outbox_events (workspace_id, deduplication_key)
  WHERE deduplication_key IS NOT NULL;
CREATE INDEX outbox_pending_idx ON outbox_events (available_at, created_at, id) WHERE published_at IS NULL;
